<script setup lang="ts">
import {ref,computed} from 'vue'
import {depthDistribution,unproject,splat} from '../utils/learningMath'
const u=ref(190),depth=ref(15),sigma=ref(3),stage=ref(3),bins=Array.from({length:13},(_,i)=>4+i*2)
const probs=computed(()=>depthDistribution(depth.value,sigma.value,bins)),samples=computed(()=>bins.map((d,i)=>{const p=unproject(u.value,120,d);return {x:p[0],y:p[2],weight:probs.value[i]}})),cells=computed(()=>splat(samples.value,3)),weight=(x:number,y:number)=>cells.value.get(`${x},${y}`)||0
</script>
<template><svg class="lab-svg" style="height:255px" viewBox="0 0 840 275" role="img" aria-label="Image, rayon 3D et accumulation BEV"><rect x="5" y="30" width="255" height="165" fill="#dceaf0"/><path d="M105 75L25 195H245L160 75Z" fill="#64748b"/><rect x="145" y="110" width="42" height="31" fill="#CF1C24"/><text x="12" y="20">1. Image + caractéristique f(u)</text><circle :cx="5+u/320*255" cy="129" r="6" fill="#F15A22" stroke="white" stroke-width="2"/><text x="12" y="215">Pixel u = {{u}}, v = 120</text><text x="12" y="240">K : fₓ = fᵧ = 200 px</text><text x="285" y="20">2. Distribuer sur les profondeurs</text><g v-if="stage>=1"><path d="M408 230L292 65L518 65Z" fill="#e5f3f7" stroke="#94a3b8"/><g v-for="(p,i) in samples" :key="i"><line x1="408" y1="230" :x2="408+p.x*7" :y2="230-p.y*5.5" stroke="#cbd5e1"/><circle :cx="408+p.x*7" :cy="230-p.y*5.5" :r="3+10*Math.sqrt(p.weight)" fill="#00BDF2" :style="{opacity:.25+.75*p.weight/Math.max(...probs)}"/><rect :x="285+i*18" :y="267-p.weight*90" width="13" :height="p.weight*90" fill="#087fa1"/></g><text x="411" y="232">Caméra</text><text x="288" y="49">Point 3D = d K⁻¹ũ</text></g><text x="566" y="20">3. Accumuler dans la grille BEV</text><g v-if="stage>=2"><g v-for="x in 8" :key="x"><rect v-for="y in 10" :key="y" :x="570+(x-1)*29" :y="240-y*21" width="28" height="20" :fill="weight(x-5,y-1)>0?'#CF1C24':'#eef2f6'" :style="{opacity:weight(x-5,y-1)>0?.25+.75*Math.min(1,weight(x-5,y-1)*3):1}" stroke="#cbd5e1"/></g><text x="570" y="263">Σ poids = {{Array.from(cells.values()).reduce((a,b)=>a+b,0).toFixed(3)}}</text></g></svg><div class="lab-controls"><label>Pixel u<input aria-label="Pixel image" v-model.number="u" type="range" min="100" max="220"/></label><label>Profondeur<input aria-label="Profondeur dominante" v-model.number="depth" type="range" min="5" max="27"/>{{depth}} m</label><label>σ<input aria-label="Incertitude profondeur" v-model.number="sigma" type="range" min="1" max="7" step=".5"/>{{sigma}} m</label><button @click="stage=(stage+1)%3">Étape</button></div><p class="lab-caption">Une caractéristique scalaire f(u) = 1 pour lire les poids ; dans le réseau, f(u) est un vecteur.</p></template>
